{"cards": [{"node_code": "N_798ebe7037a24398", "definition": "指公路养护与维修过程中采用的通用技术方法、工艺原理及检测手段，涵盖病害诊断、预防性养护策略、修复材料应用及施工质量控制等综合性技术内容。", "boundary": "本节点聚焦于“通用”或“跨结构”的养护技术原理与方法。边界在于区分“通用技术”与“特定结构养护”（若内容专门针对路基或路面的特定病害机理与修复工艺，应分别归入路基或路面养护节点）；区分“技术方法”与“管理标准”（归入养路规程与标准）及“硬件设备”（归入养路机具与设备）。", "includes": ["公路病害检测、诊断与评估的通用技术方法", "预防性养护、日常小修及专项修复的通用工艺原理", "养护施工中的质量控制、安全作业技术及新技术应用"], "excludes": ["专门针对路基结构（如边坡、排水）的养护技术", "专门针对路面结构（如沥青、水泥混凝土）的养护技术", "养路组织管理、规章制度及专用机械设备"], "sibling_distinctions": [{"other_code": "N_7407182329ad8319", "rule": "区分依据为对象特异性：本节点收录适用于路基、路面及附属设施的通用养护技术原理；路基养护节点收录专门针对路基土体、边坡、排水系统的特定养护技术。"}, {"other_code": "N_ef93c656ab901f8a", "rule": "区分依据为对象特异性：本节点收录通用养护技术；路面养护节点收录专门针对沥青、水泥混凝土等路面结构层的特定病害处理与修复技术。"}, {"other_code": "N_7dc96e42dbe85bd1", "rule": "区分依据为内容属性：本节点侧重“怎么做”的技术方法与工艺；养路机具与设备节点侧重“用什么做”的机械设备、工具及其性能与维护。"}], "cross_boundary_rule": "若内容涉及特定结构（如路面）的通用检测技术，主挂载本节点；若涉及该结构特有的修复工艺（如沥青路面灌缝），主挂载路面养护节点。"}, {"node_code": "N_7407182329ad8319", "definition": "指针对公路路基结构（包括路床、边坡、路肩、排水系统及防护工程）在运营期间出现的病害进行的检测、预防、修复及加固技术与管理内容。", "boundary": "本节点聚焦于“路基”这一特定结构层的养护。边界在于区分“路基”与“路面”（路面指行车道表面结构层，归入路面养护节点）；区分“路基养护”与“路基新建”（新建归入道路工程下的路基设计或施工）；区分“路基”与“附属构筑物”（如桥梁、隧道归入各自节点，但路基范围内的排水沟、挡土墙归本节点）。", "includes": ["路基沉降、翻浆、冻胀、边坡滑塌等病害的检测与处理技术", "路基排水系统（边沟、截水沟等）及防护工程（挡土墙、护坡）的养护", "路基日常巡查、预防性养护措施及路基加固技术"], "excludes": ["路面结构层（沥青、水泥混凝土等）的养护与维修", "桥梁、隧道等独立构筑物的养护", "新建路基的施工工艺与设计"], "sibling_distinctions": [{"other_code": "N_ef93c656ab901f8a", "rule": "区分依据为结构层次：本节点侧重路基土体、边坡及排水防护设施；路面养护节点侧重行车道表面的沥青或水泥混凝土结构层。"}, {"other_code": "N_798ebe7037a24398", "rule": "区分依据为通用性与特异性：本节点收录路基特有的病害机理与修复技术；养路技术节点收录适用于多种结构的通用检测或管理技术。"}], "cross_boundary_rule": "若病害起源于路基但表现为路面损坏（如路基沉降导致路面开裂），主挂载本节点（治本）；若仅涉及路面表层修补，主挂载路面养护节点。"}, {"node_code": "N_ef93c656ab901f8a", "definition": "指针对公路路面结构层（包括沥青路面、水泥混凝土路面及特殊铺装）在运营期间出现的裂缝、坑槽、车辙、松散等病害进行的检测、预防、修复及改善技术。", "boundary": "本节点聚焦于“路面”这一特定结构层的养护。边界在于区分“路面”与“路基”（路基指路面以下的土体结构，归入路基养护节点）；区分“路面养护”与“路面新建”（新建归入道路工程下的路面设计或施工）；区分“路面”与“附属设施”（如标线、护栏归入附属构筑物养护）。", "includes": ["沥青路面、水泥混凝土路面等常见病害（裂缝、坑槽、车辙）的检测与修复技术", "路面预防性养护（如封层、微表处）及日常小修技术", "路面性能评价、旧路面改造及特殊铺装（如透水路面）的养护"], "excludes": ["路基土体、边坡及排水设施的养护与维修", "交通标线、护栏、标志等附属设施的维护", "新建路面的施工工艺与材料设计"], "sibling_distinctions": [{"other_code": "N_7407182329ad8319", "rule": "区分依据为结构层次：本节点侧重行车道表面的铺装结构层；路基养护节点侧重路面以下的土体、边坡及排水系统。"}, {"other_code": "N_798ebe7037a24398", "rule": "区分依据为通用性与特异性：本节点收录路面特有的病害机理与修复工艺（如沥青灌缝、混凝土修补）；养路技术节点收录通用技术原理。"}], "cross_boundary_rule": "若路面损坏由路基病害引起，主挂载路基养护节点（需先处理路基）；若仅为路面表层材料老化或磨损，主挂载本节点。"}]}
